-- data_problem: 8 rows
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183727411210', 'ACOJ-1001', '1741610183786131480', 'A+B Problem', 'ACOJ', NULL, 1000, 65536, '## Problem Description Compute the sum of two integers. ## Input One line with two integers A and B (−1000 ≤ A,B ≤ 1000), separated by a space. ## Output Print one integer: A+B. ## Hint Remember the trailing newline.
', '[{"input": "1 2", "output": "3\\n"}, {"input": "-1 5", "output": "4\\n"}]', '["c", "cpp", "java", "python", "go"]', 1, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183731605515', 'ACOJ-1002', '1741610183794520090', 'Greatest Common Divisor', 'ACOJ', NULL, 1000, 65536, '## Problem Description Given two positive integers, compute their greatest common divisor (GCD). ## Input One line with two positive integers A and B (1 ≤ A,B ≤ 10^9). ## Output Print one integer: gcd(A,B).
', '[{"input": "12 18", "output": "6\\n"}, {"input": "7 1", "output": "1\\n"}]', '["c", "cpp", "java", "python", "go"]', 1, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183735799820', 'ACOJ-1003', '1741610183786131480', 'String Reverse', 'ACOJ', NULL, 1000, 65536, '## Problem Description Reverse the given string and print it. ## Input One line with a string S (length 1–100, letters and digits only). ## Output Print the reversed string.
', '[{"input": "abc", "output": "cba\\n"}, {"input": "A1b2", "output": "2b1A\\n"}]', '["c", "cpp", "java", "python", "go"]', 1, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183739994125', 'ACOJ-1004', '1741610183794520090', 'Prime Check', 'ACOJ', NULL, 1000, 65536, '## Problem Description Determine whether a positive integer is prime. ## Input One line with a positive integer N (1 ≤ N ≤ 10^6). ## Output Print Yes if N is prime, otherwise No.
', '[{"input": "2", "output": "Yes\\n"}, {"input": "1", "output": "No\\n"}]', '["c", "cpp", "java", "python", "go"]', 1, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183744188430', 'ACOJ-1005', '1741610183790325785', 'Array Sum', 'ACOJ', NULL, 1000, 65536, '## Problem Description Given n integers, compute their sum. ## Input The first line contains an integer n (1 ≤ n ≤ 1000).
The second line contains n integers (absolute value ≤ 1000), separated by spaces. ## Output Print one integer: the sum.
', '[{"input": "3\\n1 2 3", "output": "6\\n"}, {"input": "1\\n-5", "output": "-5\\n"}]', '["c", "cpp", "java", "python", "go"]', 1, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183748382735', 'ACOJ-1006', '1741610183790325785', 'Binary Search', 'ACOJ', NULL, 1000, 65536, '## Problem Description Search for a target value in a sorted ascending array. Print its 0-based index if found, otherwise −1. ## Input The first line contains two integers n and target (1 ≤ n ≤ 1000, |target| ≤ 10^9).
The second line contains n ascending integers. ## Output Print the index or −1.
', '[{"input": "5 3\\n1 2 3 4 5", "output": "2\\n"}, {"input": "4 7\\n1 3 5 9", "output": "-1\\n"}]', '["c", "cpp", "java", "python", "go"]', 2, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183752577040', 'ACOJ-1007', '1741610183786131480', 'Fibonacci', 'ACOJ', NULL, 1000, 65536, '## Problem Description Compute the n-th Fibonacci number. Define F(1)=1, F(2)=1, F(n)=F(n−1)+F(n−2). ## Input One line with an integer n (1 ≤ n ≤ 40). ## Output Print F(n).
', '[{"input": "1", "output": "1\\n"}, {"input": "5", "output": "5\\n"}]', '["c", "cpp", "java", "python", "go"]', 2, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');
INSERT INTO `data_problem` (`id`, `display_id`, `category_id`, `title`, `source`, `url`, `max_time`, `max_memory`, `description`, `test_case`, `allowed_languages`, `difficulty`, `threshold`, `use_template`, `code_template`, `is_public`, `is_visible`, `use_ai`, `solved`, `deleted`, `create_time`, `create_user`, `update_time`, `update_user`) VALUES ('1741610183756771345', 'ACOJ-1008', '1741610183790325785', 'Maximum Subarray Sum', 'ACOJ', NULL, 1000, 65536, '## Problem Description Given an integer array of length n, find the maximum sum of any contiguous subarray (at least one element). ## Input The first line contains an integer n (1 ≤ n ≤ 1000).
The second line contains n integers (absolute value ≤ 1000). ## Output Print the maximum subarray sum.
', '[{"input": "5\\n-2 1 -3 4 -1", "output": "4\\n"}, {"input": "1\\n-1", "output": "-1\\n"}]', '["c", "cpp", "java", "python", "go"]', 2, '0.50', 0, NULL, 1, 1, 0, 0, 0, '2026-11-20 19:24:56', '1', '2026-11-20 19:24:56', '1');

